-- Academy Director's newsletter: audience + suppression + issue log.
-- Generated by newsletter/sql/gen_audience.py. Do not edit the view by hand.
-- Nothing here changes any registration table: the view only reads them.

create table if not exists public.newsletter_suppressions (
  email        text primary key check (email = lower(trim(email))),
  reason       text not null check (reason in ('unsubscribed','hard_bounce','complaint','form_opt_out','manual','deleted_member','test_record')),
  source       text,
  created_at   timestamptz not null default now()
);
comment on table public.newsletter_suppressions is 'Addresses the Director''s newsletter must never be sent to: unsubscribes, hard bounces, spam complaints (synced back from the email service before every send) and manual removals. Permanent: a row is only deleted if the person re-subscribes themselves.';
alter table public.newsletter_suppressions enable row level security;
create policy newsletter_suppressions_dash_read on public.newsletter_suppressions for select to authenticated using (public.is_dashboard_user());

create table if not exists public.newsletter_issues (
  issue_no        int primary key,
  send_at         timestamptz not null,
  status          text not null default 'planned' check (status in ('planned','drafting','proof_sent','changes_requested','approved','scheduled','sent','skipped')),
  subject         text,
  preheader       text,
  proof_sent_at   timestamptz,
  approved_at     timestamptz,
  approved_note   text,
  esp_broadcast_id text,
  recipients      int,
  results         jsonb,
  notes           text,
  updated_at      timestamptz not null default now()
);
comment on table public.newsletter_issues is 'One row per fortnightly Director''s newsletter. The scheduled newsletter agent reads and updates status here: planned → proof_sent (Wed) → approved (Andy replies) → scheduled/sent (Tue 7:30pm) → results (opens, clicks, revenue) a week later.';
alter table public.newsletter_issues enable row level security;
create policy newsletter_issues_dash_read on public.newsletter_issues for select to authenticated using (public.is_dashboard_user());

create or replace view public.newsletter_opt_outs with (security_invoker = true) as
with optouts as (
  select lower(trim(parent_email)), 'form_opt_out:hallam_junior_registrations', created_at from public.hallam_junior_registrations where accept_marketing = false
  union all
  select lower(trim(parent_email)), 'form_opt_out:mickleham_junior_registrations', created_at from public.mickleham_junior_registrations where accept_marketing = false
  union all
  select lower(trim(parent_email)), 'form_opt_out:williamstown_junior_registrations', created_at from public.williamstown_junior_registrations where accept_marketing = false
  union all
  select lower(trim(email)), 'form_opt_out:program_inductions', created_at from public.program_inductions where accept_marketing = false
  union all
  select lower(trim(email)), 'form_opt_out:invitation_list_registrations', created_at from public.invitation_list_registrations where marketing_opt_in = false
  union all
  select lower(trim(email)), 'form_opt_out:lower_plenty_junior_royals_day_registrations', created_at from public.lower_plenty_junior_royals_day_registrations where marketing_opt_in = false
  union all
  select lower(trim(payload->>'email')), 'form_opt_out:archive', submitted_at from public.rra_player_submissions where (payload->>'accept_marketing') = 'false' or (payload->>'marketing_opt_in') = 'false'
  union all
  select lower(trim(payload->>'parent_email')), 'form_opt_out:archive', submitted_at from public.rra_player_submissions where (payload->>'accept_marketing') = 'false' or (payload->>'marketing_opt_in') = 'false'
  union all
  select lower(trim(email)), 'deleted_member', null::timestamptz from public.deleted_members
  union all
  select lower(trim(match_email)), 'test_record', null::timestamptz from public.rra_excluded_records
) select distinct e as email, why as reason from optouts o(e, why, at) where e is not null;
revoke all on public.newsletter_opt_outs from anon, authenticated;

