  union all
  select customer_email as raw_email, 'shop_orders_training'::text as source, 'buyers'::text as segment, created_at from public.shop_orders_training
  union all
  select customer_email as raw_email, 'shop_orders_ipl'::text as source, 'buyers'::text as segment, created_at from public.shop_orders_ipl
  union all
  select customer_email as raw_email, 'store_orders'::text as source, 'buyers'::text as segment, created_at from public.store_orders
  union all
  select parent_email as raw_email, 'store_entitlements'::text as source, 'junior'::text as segment, created_at from public.store_entitlements
  union all
  select email as raw_email, 'upcoming_program_interest'::text as source, 'leads'::text as segment, created_at from public.upcoming_program_interest
  union all
  select parent_email as raw_email, 'williamstown_junior_registrations'::text as source, 'junior'::text as segment, created_at from public.williamstown_junior_registrations
  union all
  select parent_email as raw_email, 'williamstown_open_day_registrations'::text as source, 'junior'::text as segment, created_at from public.williamstown_open_day_registrations
  union all
  select unnest(emails), 'rra_players_master', 'registry', last_seen from public.rra_players_master where coalesce(is_test,false)=false
), cleaned as (
  select lower(trim(raw_email)) as email, source, segment, created_at
  from contacts
  where raw_email is not null
), blocked as (
  select email from public.newsletter_suppressions
  union select email from public.newsletter_opt_outs
)
select c.email,
       array_agg(distinct c.segment order by c.segment) as segments,
       array_agg(distinct c.source order by c.source)   as sources,
       min(c.created_at) as first_seen,
       max(c.created_at) as last_seen
from cleaned c
where c.email ~ '^[a-z0-9._%+''-]+@[a-z0-9.-]+\.[a-z]{2,}$'
  and c.email !~ '@(example\.(com|org)|test\.com|mailinator\.com|resend\.dev)$'
  and c.email not in (select email from blocked)
group by c.email;
comment on view public.newsletter_audience is 'Every address ever registered with the Academy (all sign-up, enquiry, payment and shop tables + the canonical player registry), lower-cased and de-duplicated, minus newsletter_suppressions, explicit form opt-outs, deleted members and test records. Player-only email columns (under-18s) are deliberately not included. Read with the service role only.';
revoke all on public.newsletter_audience from anon, authenticated;


-- Who is actually sent to: minus addresses known only as coach job applicants/enquirers.
create or replace view public.newsletter_recipients with (security_invoker = true) as
select * from public.newsletter_audience
where not (segments <@ array['coaches']::text[]);
revoke all on public.newsletter_recipients from anon, authenticated;
